INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3008, 'F2', 'FIGURE', 1, 'questions/30/S3_중등_1_000184_F2.png', 254, 152, '열기구 시간에 따른 높이의 변화를 나타낸 그래프. 이미지는 시간($분$)에 따른 높이($미터$)를 나타내는 그래프이다. $X$ 축은 시간($분$)으로 $0, 5, 10, 15, 20, 25, 30$ 분이 표시되어 있고, $Y$ 축은 높이($미터$)로 $0, 100, 200, 300$ 미터가 표시되어 있다. 그래프는 특정 시간 동안 높이가 변화하는 모습을 선으로 연결해 보여주며, 높이는 $0$에서 시작해 상승과 하강을 반복하다가 $30$ 분에 이른다. 최고 높이는 $미터$0 미터에 도달하고, 최소 높이는 $미터$1 미터를 기록한다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3008 AND asset_key='F2');
UPDATE problem_question SET presentation = 'WITH_FIGURE', content_blocks = COALESCE(content_blocks, '[]'::jsonb) || '[{"text": "열기구 시간에 따른 높이의 변화를 나타낸 그래프. 이미지는 시간($분$)에 따른 높이($미터$)를 나타내는 그래프이다. $X$ 축은 시간($분$)으로 $0, 5, 10, 15, 20, 25, 30$ 분이 표시되어 있고, $Y$ 축은 높이($미터$)로 $0, 100, 200, 300$ 미터가 표시되어 있다. 그래프는 특정 시간 동안 높이가 변화하는 모습을 선으로 연결해 보여주며, 높이는 $0$에서 시작해 상승과 하강을 반복하다가 $30$ 분에 이른다. 최고 높이는 $미터$0 미터에 도달하고, 최소 높이는 $미터$1 미터를 기록한다.", "blockId": "Q-IMG-2", "assetRef": "F2", "blockKind": "FIGURE", "displayOrder": 2}]'::jsonb WHERE id = 3008;
INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3013, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000191_F1.png', 310, 148, '수정된 결과만 출력해 드리겠습니다. 속력과 시간을 나타낸 그래프이다. $y$ 축은 속력, $x$ 축은 시간이다. $0$ 분 일 때 속도는 $0$ 이다. $5$ 분 일 때 속력은 $30$ 이다. $10$ 분 일 때 속력은 $30$ 이다. $15$ 분 일 때 속력은 $0$ 이다. $x$0분 일 때 속력은 $0$ 이다. $x$2분 일 때 속력은 $x$3 이다. $30$ 분 일 때 속력은 $x$3 이다. $x$6분 일 때 속력은 $0$ 이다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3013 AND asset_key='F1');
UPDATE problem_question SET presentation = 'WITH_FIGURE', content_blocks = COALESCE(content_blocks, '[]'::jsonb) || '[{"text": "수정된 결과만 출력해 드리겠습니다. 속력과 시간을 나타낸 그래프이다. $y$ 축은 속력, $x$ 축은 시간이다. $0$ 분 일 때 속도는 $0$ 이다. $5$ 분 일 때 속력은 $30$ 이다. $10$ 분 일 때 속력은 $30$ 이다. $15$ 분 일 때 속력은 $0$ 이다. $x$0분 일 때 속력은 $0$ 이다. $x$2분 일 때 속력은 $x$3 이다. $30$ 분 일 때 속력은 $x$3 이다. $x$6분 일 때 속력은 $0$ 이다.", "blockId": "Q-IMG-1", "assetRef": "F1", "blockKind": "FIGURE", "displayOrder": 1}]'::jsonb WHERE id = 3013;
INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3079, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000182_F1.png', 198, 159, '거리와 시간(분)을 나타낸 그래프. 이 이미지는 거리(킬로미터)와 시간(분) 간의 관계를 나타낸 그래프입니다. 그래프는 시간에 따라 이동 거리가 어떻게 변화하는지를 보여주고 있으며, 특정 시간이 지날 때의 이동 거리가 $4km$로 일정함을 나타냅니다. $60$분에서 $90$분 사이에 최대 거리에 도달합니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3079 AND asset_key='F1');
