INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3090, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000185_F1.png', 249, 199, '이 이미지는 튜브의 높이와 시간을 나타내는 그래프입니다. 그래프는 시간(초)를 가로축으로하고, 튜브의 부피를 세로축으로 표시하고 있습니다. 그래프는 $0$초에서 시작하여 $3$초와 $7$초에서 가장 높은 지점을 나타내며, 최종적으로 $13$초까지 진행됩니다. 질문은 열기구가 가장 높이 올라간 높이에 대한 것으로 보입니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3090 AND asset_key='F1');
UPDATE problem_question SET presentation = 'WITH_FIGURE', content_blocks = COALESCE(content_blocks, '[]'::jsonb) || '[{"text": "이 이미지는 튜브의 높이와 시간을 나타내는 그래프입니다. 그래프는 시간(초)를 가로축으로하고, 튜브의 부피를 세로축으로 표시하고 있습니다. 그래프는 $0$초에서 시작하여 $3$초와 $7$초에서 가장 높은 지점을 나타내며, 최종적으로 $13$초까지 진행됩니다. 질문은 열기구가 가장 높이 올라간 높이에 대한 것으로 보입니다.", "blockId": "Q-IMG-1", "assetRef": "F1", "blockKind": "FIGURE", "displayOrder": 1}]'::jsonb WHERE id = 3090;
