INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3095, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000189_F1.png', 218, 167, '이미지는 시간에 따른 거리 변화를 나타내는 그래프입니다. 해당 그래프는 거리(km)를 y축에, 시간(분)을 x축에 두고 있습니다. 그래프는 0에서 시작하여 30분과 60분 사이에 2km에 도달한 후, 100분까지 일정한 거리를 유지하다가 다시 0으로 돌아가는 형태를 보여줍니다. 이 그래프는 주로 속도나 이동 시간과 관련된 문제를 설명하는 데 사용됩니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3095 AND asset_key='F1');
