INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3098, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000191_F1.png', 310, 148, '수정된 결과만 출력해 드리겠습니다. 속력과 시간을 나타낸 그래프이다. $y$ 축은 속력, $x$ 축은 시간이다. $0$ 분 일 때 속도는 $0$ 이다. $5$ 분 일 때 속력은 $30$ 이다. $10$ 분 일 때 속력은 $30$ 이다. $15$ 분 일 때 속력은 $0$ 이다. $x$0분 일 때 속력은 $0$ 이다. $x$2분 일 때 속력은 $x$3 이다. $30$ 분 일 때 속력은 $x$3 이다. $x$6분 일 때 속력은 $0$ 이다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3098 AND asset_key='F1');
