INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3108, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000228_F1.png', 212, 140, '가로의 길이가 $80cm$. 세로의 길이가 $50cm$ 인 창문. 이 이미지는 슬라이딩 도어의 설계를 나타냅니다. 왼쪽에는 면적이 $y cm^2$인 공간이 있고, 오른쪽에는 두 개의 슬라이딩 도어가 있으며, 전체의 높이는 $50cm$, 너비는 $80cm$입니다. 추가로 $x cm^2$라는 면적이 표시되어 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3108 AND asset_key='F1');
UPDATE problem_question SET presentation = 'WITH_FIGURE', content_blocks = COALESCE(content_blocks, '[]'::jsonb) || '[{"text": "가로의 길이가 $80cm$. 세로의 길이가 $50cm$ 인 창문. 이 이미지는 슬라이딩 도어의 설계를 나타냅니다. 왼쪽에는 면적이 $y cm^2$인 공간이 있고, 오른쪽에는 두 개의 슬라이딩 도어가 있으며, 전체의 높이는 $50cm$, 너비는 $80cm$입니다. 추가로 $x cm^2$라는 면적이 표시되어 있습니다.", "blockId": "Q-IMG-1", "assetRef": "F1", "blockKind": "FIGURE", "displayOrder": 1}]'::jsonb WHERE id = 3108;
INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3112, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000214_F1.png', 179, 187, '이 이미지는 진동수(Hz)에 따른 파장의 그래프입니다. 그래프는 감소하는 곡선 형태로, 진동수가 증가할수록 파장이 감소함을 나타냅니다. x축은 진동수, y축은 파장을 나타냅니다. 녹색의 곡선이 파장 $6. 80$, 진동수 $50$인 구간을 지나갑니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3112 AND asset_key='F1');
UPDATE problem_question SET presentation = 'WITH_FIGURE', content_blocks = COALESCE(content_blocks, '[]'::jsonb) || '[{"text": "이 이미지는 진동수(Hz)에 따른 파장의 그래프입니다. 그래프는 감소하는 곡선 형태로, 진동수가 증가할수록 파장이 감소함을 나타냅니다. x축은 진동수, y축은 파장을 나타냅니다. 녹색의 곡선이 파장 $6. 80$, 진동수 $50$인 구간을 지나갑니다.", "blockId": "Q-IMG-1", "assetRef": "F1", "blockKind": "FIGURE", "displayOrder": 1}]'::jsonb WHERE id = 3112;
