INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3127, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000228_F1.png', 212, 140, '가로의 길이가 $80cm$. 세로의 길이가 $50cm$ 인 창문. 이 이미지는 슬라이딩 도어의 설계를 나타냅니다. 왼쪽에는 면적이 $y cm^2$인 공간이 있고, 오른쪽에는 두 개의 슬라이딩 도어가 있으며, 전체의 높이는 $50cm$, 너비는 $80cm$입니다. 추가로 $x cm^2$라는 면적이 표시되어 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3127 AND asset_key='F1');
