INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3226, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000383_F1.png', 207, 198, '사각형에 내접하는 삼각형이 그려져 있음. 사각형의 가로 길이는 $10$, 세로 길이는 $8$. 삼각형의 밑변 길이는 $x$로 표시됨.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3226 AND asset_key='F1');
