INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3294, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000436_F1.png', 279, 226, '이 이미지는 좌표평면에 그려진 선형 그래프를 보여준다. 가로축은 x축으로, 0부터 7까지의 값을 가지며, 단위는 ''분''으로 표시되어 있다. 세로축은 y축으로, 0부터 150까지의 값을 가지며, 단위는 ''m''(미터)로 표시되어 있다. 그래프의 선은 일정한 기울기를 가지며, 여러 점을 연결하여 직선 형태로 나타난다. 주어진 x 값에 대한 y 값이 점진적으로 증가하는 모습을 보여준다. 그래프의 색상은 주황색이고, 구획이 나누어진 격자 형태로 배치되어 있다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3294 AND asset_key='F1');
