INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3296, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000437_F1.png', 366, 199, '이 이미지는 일별 기온 변화 그래프입니다. 수직축은 기온(°C)이고, 수평축은 날짜(1일부터 10일)가 나타나 있습니다. 각 점은 특정 날짜의 기온을 나타내며, 전체적으로 기온이 상승하는 경향을 보이고 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3296 AND asset_key='F1');
