INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3299, 'F2', 'FIGURE', 1, 'questions/30/S3_중등_1_000438_F2.png', 501, 236, '㉮ 그래프는 부드럽게 상승하는 곡선 형태로, 높이가 시간에 따라 점점 증가하는 방식이다. 초기에는 완만하다가 시간이 지남에 따라 더욱 가파르게 상승하는 모습이다. ㉯ 그래프는 직선으로, 높이가 시간에 비례하여 일정하게 증가하고 있다. 이는 일정한 속도로 높이가 증가하는 것을 나타낸다. ㉰ 그래프는 먼저 완만하게 상승하다가 시간이 지나면서 점점 경사가 커지는 곡선 형태이다. 처음에는 서서히 증가하다가 나중에는 더 빠른 속도로 높이가 증가한다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3299 AND asset_key='F2');
