INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3315, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000453_F1.png', 308, 180, '시간에 따른 기온 변화를 나타낸 그래프. 이 이미지는 시간에 따른 온도의 변화를 나타낸 그래프입니다. X축은 시간(시)를, Y축은 온도(°C)를 나타내고 있으며, 온도가 시간에 따라 어떻게 변화하는지를 보여줍니다. 그래프의 형태와 점선은 특정 시간대의 온도를 표시하고 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3315 AND asset_key='F1');
