INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3391, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000558_F1.png', 165, 157, '이미지는 육면체의 일종인 사각기둥 또는 비스듬히 세운 기둥을 나타낸다. 꼭짓점은 A, B, C, D, E, F로 표시되어 있다. 면은 다음과 같이 구성되어 있다: - 밑면: ABC - 윗면: DEF - 측면: ABF, ABE, ACD, BCD, CEF, DEF E는 면 ABC와 DEF에서 연결된 중간 점으로 보인다. 선들이 점 E를 연결하여 여러 면들이 교차하는 모습을 보여준다. 이 도형은 3차원으로, 좀 더 복잡한 구조를 갖고 있다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3391 AND asset_key='F1');
