INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3499, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000716_F1.png', 184, 175, '이미지에는 세 개의 큰 삼각형이 서로 맞닿아 있는 형태로 배열되어 있다. 각 삼각형의 꼭짓점에는 대문자가 배치되어 있고, 그 안에는 작은 각도 수치가 있는 소문자가 있다. - 상단 삼각형: - 꼭짓점 A - 오른쪽 꼭짓점 F - 왼쪽 꼭짓점 B - 각도: a (A), f (F) - 중간 삼각형: - 꼭짓점 G - 오른쪽 꼭짓점 I - 왼쪽 꼭짓점 C - 각도: b (G), c (C) - 하단 삼각형: - 꼭짓점 H - 오른쪽 꼭짓점 D - 왼쪽 꼭짓점 E - 각도: d (H), e (D) 배경은 회색이며, 각 삼각형의 내부 구조가 명확하게 구분된다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3499 AND asset_key='F1');
