INSERT INTO problem_asset (question_id, asset_key, role, display_order, storage_key, width_px, height_px, alt_text) SELECT 3576, 'F1', 'FIGURE', 0, 'questions/30/S3_중등_1_000803_F1.png', 204, 159, '어느 지역의 8월 한 달 동안의 불쾌지수를 조사하여 나타낸 히스토그램입니다. $x$축은 점수를 나타내고, $y$축은 각 점수 구간에 해당하는 데이터의 개수를 나타냅니다. 점수 구간은 $60$부터 $90$까지이며, 각 구간의 데이터 개수는 다음과 같습니다: - $60$: $2$ - $65$: $6$ - $70$: $9$ - $y$0: $y$1 - $y$2: $y$3 - $y$4: $y$5 가장 높은 데이터 개수는 $70$점 구간에 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM problem_asset WHERE question_id=3576 AND asset_key='F1');
